insertAtCursor.$method:
insertAtCursor(textToInsert) {
        const textarea = this.$refs.promptEditor;
        if (!textarea) {
            this.promptText += '\n' + textToInsert;
            return;
        }
        const start = textarea.selectionStart;
        const end = textarea.selectionEnd;
        const textBefore = this.promptText.substring(0, start);
        const textAfter = this.promptText.substring(end);
        
        this.promptText = textBefore + textToInsert + textAfter;
        this.activePopover = null;
        
        this.$nextTick(() => {
            textarea.focus();
            textarea.setSelectionRange(start + textToInsert.length, start + textToInsert.length);
        });
    }

selectTaskTab.$method:
selectTaskTab(tab) {
        if (tab === 'hints' && !this.unlockedHints) {
            this.lockWarningTarget = 'hints';
            this.showLockWarning = true;
            return;
        }
        if (tab === 'solution' && !this.unlockedSolution) {
            this.lockWarningTarget = 'solution';
            this.showLockWarning = true;
            return;
        }
        this.activeTaskTab = tab;
    }

confirmUnlock.$method:
confirmUnlock() {
        if (this.lockWarningTarget === 'hints') {
            this.unlockedHints = true;
            this.activeTaskTab = 'hints';
        } else if (this.lockWarningTarget === 'solution') {
            this.unlockedSolution = true;
            this.activeTaskTab = 'solution';
        }
        this.showLockWarning = false;
        this.lockWarningTarget = null;
    }

