get filteredDirectory() {
        return this.codelabDirectory.filter(lab => {
            let matchSearch = lab.title.toLowerCase().includes(this.searchQuery.toLowerCase()) || 
                              lab.code.toLowerCase().includes(this.searchQuery.toLowerCase());
            let matchState = this.filterState === 'ALL' || lab.state === this.filterState;
            let matchClient = this.filterClient === 'ALL' || lab.client === this.filterClient;
            let matchPillar = this.filterPillar === 'ALL' || lab.pillar === this.filterPillar;
            return matchSearch && matchState && matchClient && matchPillar;
        });
    }

