rebalanceActiveRubric.$method:
rebalanceActiveRubric() {
        let activeKeys = Object.keys(this.rubricCriteria).filter(k => this.rubricCriteria[k].active);
        Object.keys(this.rubricCriteria).forEach(k => {
            if (!this.rubricCriteria[k].active) this.rubricCriteria[k].weight = 0;
        });

        if (activeKeys.length === 0) return;

        let currentActiveSum = activeKeys.reduce((sum, k) => sum + Number(this.rubricCriteria[k].weight), 0);

        if (currentActiveSum === 0) {
            let equalShare = Math.floor(100 / activeKeys.length);
            let remainder = 100 - (equalShare * activeKeys.length);
            activeKeys.forEach((k, idx) => {
                this.rubricCriteria[k].weight = equalShare + (idx === 0 ? remainder : 0);
            });
        } else {
            let remainingTarget = 100;
            activeKeys.forEach((k, idx) => {
                if (idx === activeKeys.length - 1) {
                    this.rubricCriteria[k].weight = Math.max(0, remainingTarget);
                } else {
                    let share = Math.round((Number(this.rubricCriteria[k].weight) / currentActiveSum) * 100);
                    this.rubricCriteria[k].weight = Math.max(0, share);
                    remainingTarget -= share;
                }
            });
        }
    }

updateWeight.$method:
updateWeight(changedKey, newValue) {
        if (!this.rubricCriteria[changedKey].active) return;
        let val = Math.max(0, Math.min(100, Number(newValue)));
        this.rubricCriteria[changedKey].weight = val;

        let otherActiveKeys = Object.keys(this.rubricCriteria).filter(k => k !== changedKey && this.rubricCriteria[k].active);
        if (otherActiveKeys.length === 0) {
            this.rubricCriteria[changedKey].weight = 100;
            return;
        }

        let targetOtherSum = 100 - val;
        let currentOtherSum = otherActiveKeys.reduce((sum, k) => sum + Number(this.rubricCriteria[k].weight), 0);

        if (currentOtherSum > 0) {
            let remainingTarget = targetOtherSum;
            otherActiveKeys.forEach((k, idx) => {
                if (idx === otherActiveKeys.length - 1) {
                    this.rubricCriteria[k].weight = Math.max(0, remainingTarget);
                } else {
                    let share = Math.round((Number(this.rubricCriteria[k].weight) / currentOtherSum) * targetOtherSum);
                    this.rubricCriteria[k].weight = Math.max(0, share);
                    remainingTarget -= share;
                }
            });
        } else {
            let equalShare = Math.floor(targetOtherSum / otherActiveKeys.length);
            let remainder = targetOtherSum - (equalShare * otherActiveKeys.length);
            otherActiveKeys.forEach((k, idx) => {
                this.rubricCriteria[k].weight = equalShare + (idx === 0 ? remainder : 0);
            });
        }
    }

totalWeight.$getter:
get totalWeight() {
        return Object.values(this.rubricCriteria).reduce((sum, c) => sum + Number(c.weight), 0);
    }

